# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["用户最早提的要求里有一句：我希望你能在大屏把我的交易因果表达出来，我要知道你在做什么。","","board.js 那 554 行是我一行行写的，但我从来没有真的让它跑起来看过。","这一轮我给它搭了个无头渲染台，第一次看到它到底会印出什么。","","=== 一、先走错了一步，记下来 ===","","我先用正则把 board.js 里所有字段访问抠出来，和真实 API 返回对照，","结论是 45 个存在、33 个缺失，看起来一片红。","","但我差点就此动手去补后端字段。停了一下先核对，发现全是假警报：","  - g 既是 guard，也是 canvas 的 2d 上下文（g.fillStyle 被当成 guard.fill）","  - s 在一处是 stats，在另一处是 feed 快照（applyState 的入参）","  - st 在局部是 data[msg.i]","变量名遮蔽把我骗了。真正的结论是：","applyState 收到的是 feed 快照，ws_idle_ms / rest_latency_ms / ticks_total /","uptime_s 都在里面，大屏这一行没有任何问题。","","如果当时照着那份「33 个缺失」去补，我会往后端塞一堆本来就有、或者根本不该有的字段。","这就是过度修复，而且改完还会显得很忙。","","=== 二、换对方法之后，真缺陷立刻现形 ===","","不再靠读代码猜，改为：用 node 起一个最小 DOM 桩，让 board.js 真跑一遍，","喂 9 种合成状态，把渲染出来的每个字抓出来，断言里面不出现 undefined / NaN。","","这一跑，三条真缺陷同时现身，而且都在同一张卡片上——持仓卡：","","  1. 目标 NaN","     后端 snap[pos] 只有 side/qty/entry/stop/entry_ts 五个键，根本没有 target；","     而大屏写着 Number(p.target).toFixed(1)。Number(undefined) = NaN。","","  2. 已持有 undefined 根 3s","     后端 pos 里也没有 bars。这是剥头皮时代留下的写法，","     而趋势持仓的计量单位是小时。","","  3. 浮动盈亏 -93.600U","     这条最要命。开仓 78000、现价 82000、0.0012 BTC，","     真实浮盈应该是 +4.8U，却显示 -93.6U —— 那正好等于整笔名义额，","     看起来像全亏光了。","     原因：整张卡片的数据都来自 REST，唯独浮盈用了 state.price，","     而 state.price 是 WS 快照喂的。WS 一降级它就是 0 或陈旧值。","     也就是说：这张卡片会在【最需要看清真实盈亏的时刻】给出最荒谬的数。","","这三条有一个共同点：它们只在【持仓时】才渲染，","而这个账户一次都没持仓过——所以它们潜伏到现在，","并且会在钱到账、第一次开仓的瞬间全部现形。","","=== 三、修法 ===","","  - 浮盈价格改用这条 REST 消息自带的 st.trend.price，缺失才退回 state.price；","    价格未知时明写「价格未知（数据源异常）」，不印一个假数字。","  - 目标：趋势策略本来就没有固定止盈，改为显示「无（跌破均线出场）」。","  - 已持有：优先用 hold_h 小时，退回 entry_ts 推算，最后才是 —。","  - 连续亏损补兜底。这条是防御性的：后端其实总是下发它，","    所以我的变异验证第一轮没抓住它——我如实记下来，","    并补了一个「risk 字段不全」的状态把它钉住，而不是假装它已经被验证过。","","=== 四、验证 ===","","新增 13 条用例（9 种状态 x 不出现 undefined/NaN + 持仓卡片语义断言 + 对照）。","全量 352 条全绿。4 处变异全部被抓住。","","最重要的是最后一步：我把【线上真实 API 返回】抓下来，用同一个渲染台跑了一遍。","结果 0 个 undefined / NaN，而且因果链读起来是这样的——","","  4h K线 419 根 -> SMA200 82323.8 -> 现价 78109.0（-5.12%）","  -> 下跌趋势（价在均线下方） -> 安全闸放行，回撤 0.0%（硬停线 60%）","  -> 动作：空仓等待","  -> 开多触发线：涨到 82488.4（还需 +5.61%）并收盘确认","     （SMA 82323.8 x 1+0.20%，避开擦边的假突破）","  -> 若价格一直不动，均线自己下来也到不了这条线","","这就是用户要的那个东西：不是一堆数字，是一条能读下来的因果链。","","顺带记一个数：硬停线是 60%，而历史最深回撤 47.8%——余量只有 12 个百分点。","这个值以后要单独评估，本轮不动它。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":73,"theme":"给大屏搭无头渲染台，第一次看到它印什么；抓到三条只在持仓时才现形的缺陷","false_alarm_first":{"what":"先用正则把 board.js 的字段访问和真实 API 对照，得出 45 存在/33 缺失","why_wrong":"变量名遮蔽：g 既是 guard 又是 canvas 2d 上下文；s 一处是 stats、一处是 feed 快照；st 局部是 data[msg.i]","real_answer":"applyState 收到的是 feed 快照，ws_idle_ms/rest_latency_ms/ticks_total/uptime_s 都在里面，那一行没问题","lesson":"若照那份 33 缺失去补，会往后端塞一堆本来就有或不该有的字段——过度修复且显得很忙"},"method":"node + 最小 DOM 桩加载 board.js，喂合成状态，抓渲染文本，断言无 undefined/NaN；状态键集取自实测的 /api/trade/state","defects":[{"field":"目标","bug":"后端 snap[pos] 只有 5 个键，没有 target；大屏 Number(p.target).toFixed(1) -> NaN","fix":"target<=0 时显示「无（跌破均线出场）」"},{"field":"已持有","bug":"后端 pos 无 bars；剥头皮时代写法「N 根 3s」，趋势持仓应为小时","fix":"优先 hold_h，退回 entry_ts 推算，最后 —"},{"field":"浮动盈亏","bug":"整卡数据来自 REST，唯独浮盈用 WS 的 state.price；WS 降级时为 0/陈旧 -> 实测开仓78000现价82000却显示 -93.600U（等于整笔名义），真实应为 +4.8U","fix":"改用 st.trend.price（同一条 REST 消息），缺失才退回 state.price；价格未知时明写「价格未知」不印假数"},{"field":"连续亏损","bug":"无兜底，后端若少给会印 undefined","fix":"||0 兜底（防御性；后端当前总是下发，故额外补一个「risk 字段不全」状态来钉住它）"}],"why_latent":"三条都只在持仓时渲染，而账户一次都没持仓过——会在钱到账、第一次开仓瞬间全部现形","verification":{"tests":352,"new_tests":13,"mutations":4,"mutations_all_red":true,"real_state_render":"抓线上真实 API 返回跑同一渲染台：0 个 undefined/NaN","deploy":"board.js / harness / test md5 双端一致, 0 ERROR, 三服务 active"},"observed":{"hard_stop_line_pct":60,"historical_max_dd_pct":47.8,"note":"余量仅 12 个百分点，以后单独评估，本轮不动"},"account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'给大屏搭了个无头渲染台，第一次看到它印什么：三条只在持仓时才现形的缺陷',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()